			function setTotalCount() {
			    // 통합인원수 카운트를 위한 데이터 셋 생성
			    var voDsTotal = app.lookup("dsTotal");
			    
			    voDsTotal.clearData();
			    
			    app.lookup("dsCyberTime").copyToDataSet(voDsTotal);
			    // 모바일 관련 삭제
			    app.lookup("dsMobileTime").copyToDataSet(voDsTotal);
			    app.lookup("dsOutReachTime").copyToDataSet(voDsTotal);
			    
			    // 상담사 ID를 기준으로 구분
			//    var vnTotalCount = voDsTotal.getUnfilteredDistinctValues("CONS_ID").length;
			    var aa = 0;
			    var vnTotalCount = voDsTotal.getUnfilteredDistinctValues("CONS_ID", function(rowData) {
			        aa++;
			//        console.log(aa+".CONS_ID : "+rowData.getValue("CONS_ID")+"   "+rowData.getValue("CONS_NAME"));
			        return rowData.getValue("CONS_ID") != ""
			    }).length;
			    aa = 1000;
			    var vnHoliCount = voDsTotal.getUnfilteredDistinctValues("CONS_ID", function(rowData) {
			        aa++;
			//        console.log(aa+".CONS_ID : "+rowData.getValue("CONS_ID")+"   "+rowData.getValue("CONS_NAME")+"   "+rowData.getValue("HOLI_STATUS"));
			        return rowData.getValue("HOLI_STATUS") == "승인"
			    }).length;
			    
			    var vnWorkCount = vnTotalCount - vnHoliCount;
			    app.lookup("optTotal").value = "· 전체  :  " + vnTotalCount + "명   · 근무  :  " + vnWorkCount + "명   · 휴가  :  " + vnHoliCount + "명";
			}

